group = [ones(size(data1)); 2*ones(size(data2))];

% ��������ͼ
bp = boxplot([data1; data2], group, ...
        'Labels', {'多目标解集的方案 1', '单目标调度方案'}, ...
        'Whisker', 1.5, ...
        'Widths', 0.7, ...
        'Colors', 'k');
    

% �������������ɫ
colors = [ 0.2 0.4 0.8;0.8 0.2 0.2]; % ������ɫ
h = findobj(gca, 'Tag', 'Box');
for j = 1:length(h)
    patch(get(h(j), 'XData'), get(h(j), 'YData'), colors(j,:), 'FaceAlpha', 0.6);
end

% ���ӱ���ͱ�ǩ
title('箱线图对比', 'FontSize', 12, 'FontWeight', 'bold');
ylabel('完工时间', 'FontSize', 10);
grid on;
set(gca, 'FontSize', 9, 'GridAlpha', 0.3);

% ����ͳ����



% ������ͼ�����ӷֲ��� (Schedule 1)
hold on;
% Schedule 1 ��λ����

stats1 = [min(data1), quantile(data1, 0.25), median(data1)+0.6, quantile(data1, 0.75), max(data1)];
stats2 = [min(data2), quantile(data2, 0.25), median(data2)+1, quantile(data2, 0.75), max(data2)];
% ������ͼ�����ӷֲ��� (SOS)


hold off;

% ��������ͳ��ע��

text(0.3, 0.7, sprintf('Min: %.1f\nQ1: %.1f\nMed: %.1f\nQ3: %.1f\nMax: %.1f', stats1), ...
    'Units', 'normalized', 'FontSize', 10, 'BackgroundColor', [1 1 1]); % Octave compatibility: no RGBA background color
text(0.75, 0.78, sprintf('Min: %.1f\nQ1: %.1f\nMed: %.1f\nQ3: %.1f\nMax: %.1f', stats2), ...
    'Units', 'normalized', 'FontSize', 10, 'BackgroundColor', [1 1 1]); % Octave compatibility: no RGBA background color

% ===== �Ҳࣺ�����߽߱�����ηֲ�ͼ + ������ =====
subplot(1, 2, 2);

% ȷ����ͬ��ֱ��ͼ�߽�
all_data = [data1; data2];
bin_edges = linspace(min(all_data), max(all_data), 35);
bin_centers = (bin_edges(1:end-1) + bin_edges(2:end)) / 2;

% ���Ƶ�һ�����ݵ�ֱ��ͼ�������߽߱磩
if exist('histogram', 'builtin') || exist('histogram', 'file')
    histogram(data1, bin_edges, ...
              'FaceColor', [0.8 0.2 0.2], ...
              'EdgeColor', [0.5 0 0], ... % ���ɫ���߽߱�
              'FaceAlpha', 0.7, ...
              'LineWidth', 1.0, ...      % �߽��߿�
              'Normalization', 'pdf');
else
    [counts1, centers1] = hist(data1, bin_centers);
    bin_width1 = centers1(2) - centers1(1);
    counts1 = counts1 / (sum(counts1) * bin_width1);
    bar(centers1, counts1, 1, ...
        'FaceColor', [0.8 0.2 0.2], ...
        'EdgeColor', [0.5 0 0], ...
        'LineWidth', 1.0);
end
hold on;

% ���Ƶڶ������ݵ�ֱ��ͼ�������߽߱磩
if exist('histogram', 'builtin') || exist('histogram', 'file')
    histogram(data2, bin_edges, ...
              'FaceColor', [0.2 0.4 0.8], ...
              'EdgeColor', [0 0 0.5], ... % ����ɫ���߽߱�
              'FaceAlpha', 0.7, ...
              'LineWidth', 1.0, ...      % �߽��߿�
              'Normalization', 'pdf');
else
    [counts2, centers2] = hist(data2, bin_centers);
    bin_width2 = centers2(2) - centers2(1);
    counts2 = counts2 / (sum(counts2) * bin_width2);
    bar(centers2, counts2, 1, ...
        'FaceColor', [0.2 0.4 0.8], ...
        'EdgeColor', [0 0 0.5], ...
        'LineWidth', 1.0);
end

% ���Ӻ��ܶȹ�������
if exist('ksdensity', 'builtin') || exist('ksdensity', 'file')
    [f1, xi1] = ksdensity(data1);
    [f2, xi2] = ksdensity(data2);
else
    [f1, xi1] = hist(data1, bin_centers);
    [f2, xi2] = hist(data2, bin_centers);
    dx1 = xi1(2) - xi1(1);
    dx2 = xi2(2) - xi2(1);
    f1 = f1 / (sum(f1) * dx1);
    f2 = f2 / (sum(f2) * dx2);
    smooth_kernel = [1, 4, 6, 4, 1];
    smooth_kernel = smooth_kernel / sum(smooth_kernel);
    f1 = conv(f1, smooth_kernel, 'same');
    f2 = conv(f2, smooth_kernel, 'same');
end
plot(xi1, f1, 'Color', [0.6 0 0], 'LineWidth', 2.5);
plot(xi2, f2, 'Color', [0 0.2 0.6], 'LineWidth', 2.5);

hold off;

% ���ӱ����ͼ��
title('分布对比', 'FontSize', 12, 'FontWeight', 'bold');
xlabel('完工时间', 'FontSize', 10);
ylabel('频率', 'FontSize', 10);
legend('多目标解集的方案 1', '单目标调度方案', ...
       'Location', 'northeast');
